using System;
using System.Collections.Generic;
using UnityEngine;

public class Outfit
{
	public string outfitID;

	public int outfitColorIndex;

	public List<OutfitModStat> modList;

	private string description;

	public List<NumVarStatMod> lvlModList = new List<NumVarStatMod>();

	private NumVarStatMod currentMod;

	public float levelModInc = 0.0025f;

	public SyncedNumVarStat levelModStat = new SyncedNumVarStat(0.5f);

	public Player parentPlayer;

	public bool unlocked;

	public bool useLeveling;

	private static string lvlStr = "Level";

	private static Outfit _savileOutfit;

	private static Dictionary<string, Outfit> outfitDict;

	public static string normalID = ElementType.Chaos.ToString();

	public static Outfit normalOutfit = new Outfit(normalID, 24, new List<OutfitModStat>(), isUnlocked: true);

	private static List<Outfit> outfitList;

	public static Outfit baseHope = new Outfit("Hope", 0, new List<OutfitModStat>
	{
		new OutfitModStat()
	}, isUnlocked: true);

	public static Outfit basePatience = new Outfit("Patience", 11, new List<OutfitModStat>
	{
		new OutfitModStat()
	}, isUnlocked: true);

	public static Outfit enhancedHope = new Outfit("Hope", 0, new List<OutfitModStat>
	{
		new OutfitModStat(OutfitModStat.OutfitModType.Health, 0f, 0.05f),
		new OutfitModStat(OutfitModStat.OutfitModType.Speed, 0f, 0.1f),
		new OutfitModStat(OutfitModStat.OutfitModType.Damage, 0f, 0.05f),
		new OutfitModStat(OutfitModStat.OutfitModType.CritChance, 0.05f)
	}, isUnlocked: true);

	public static Outfit enhancedPatience = new Outfit("Patience", 11, new List<OutfitModStat>
	{
		new OutfitModStat(OutfitModStat.OutfitModType.Health, 0f, 0.05f),
		new OutfitModStat(OutfitModStat.OutfitModType.Speed, 0f, 0.1f),
		new OutfitModStat(OutfitModStat.OutfitModType.Armor, 0.05f),
		new OutfitModStat(OutfitModStat.OutfitModType.Evade, 0.05f)
	}, isUnlocked: true);

	public static Outfit SavileOutfit
	{
		get
		{
			if (_savileOutfit == null)
			{
				_savileOutfit = new Outfit("Savile", 0, new List<OutfitModStat>
				{
					new OutfitModStat(OutfitModStat.OutfitModType.Health, 0f, 0.05f),
					new OutfitModStat(OutfitModStat.OutfitModType.Speed, 0f, 0.1f),
					new OutfitModStat(OutfitModStat.OutfitModType.Evade, 0.05f),
					new OutfitModStat(OutfitModStat.OutfitModType.Cooldown, 0f, -0.1f)
				});
			}
			return _savileOutfit;
		}
	}

	public static Dictionary<string, Outfit> OutfitDict
	{
		get
		{
			if (outfitDict == null)
			{
				UpdateOutfitDictData();
			}
			return outfitDict;
		}
	}

	public static List<Outfit> OutfitList
	{
		get
		{
			List<Outfit> list = outfitList;
			if (list == null)
			{
				List<Outfit> list2 = new List<Outfit>();
				list2.Add(baseHope);
				list2.Add(basePatience);
				list2.Add(new Outfit("Vigor", 20, new List<OutfitModStat>
				{
					new OutfitModStat(OutfitModStat.OutfitModType.Health, 0f, 0.1f),
					new OutfitModStat(OutfitModStat.OutfitModType.Cooldown, 0f, -0.1f)
				}));
				list2.Add(new Outfit("Grit", 17, new List<OutfitModStat>
				{
					new OutfitModStat(OutfitModStat.OutfitModType.Armor, 0.1f),
					new OutfitModStat(OutfitModStat.OutfitModType.HealAmount, 0f, 0.1f)
				}));
				list2.Add(new Outfit("Greed", 18, new List<OutfitModStat>
				{
					new OutfitModStat(OutfitModStat.OutfitModType.Platinum, 1f),
					new OutfitModStat(OutfitModStat.OutfitModType.Gold, 0f, 0.1f)
				}));
				list2.Add(new Outfit("Pink", 14, new List<OutfitModStat>
				{
					new OutfitModStat(OutfitModStat.OutfitModType.HealAmount, 0f, 0.2f),
					new OutfitModStat(OutfitModStat.OutfitModType.HealCrit, 0.1f)
				}));
				list2.Add(new Outfit("Pace", 3, new List<OutfitModStat>
				{
					new OutfitModStat(OutfitModStat.OutfitModType.Speed, 0f, 0.15f),
					new OutfitModStat(OutfitModStat.OutfitModType.Run, 0f, -0.3f)
				}));
				list2.Add(new Outfit("Tempo", 5, new List<OutfitModStat>
				{
					new OutfitModStat(OutfitModStat.OutfitModType.Cooldown, 0f, -0.15f),
					new OutfitModStat(OutfitModStat.OutfitModType.Speed, 0f, 0.1f)
				}));
				list2.Add(new Outfit("Switch", 4, new List<OutfitModStat>
				{
					new OutfitModStat(OutfitModStat.OutfitModType.Evade, 0.1f),
					new OutfitModStat(OutfitModStat.OutfitModType.CritChance, 0.05f)
				}));
				list2.Add(new Outfit("Awe", 6, new List<OutfitModStat>
				{
					new OutfitModStat(OutfitModStat.OutfitModType.CritChance, 0.1f),
					new OutfitModStat(OutfitModStat.OutfitModType.CritDamage, 0.25f)
				}));
				list2.Add(new Outfit("Fury", 8, new List<OutfitModStat>
				{
					new OutfitModStat(OutfitModStat.OutfitModType.ODRate, 0f, 0.2f),
					new OutfitModStat(OutfitModStat.OutfitModType.ODDamage, 0f, 0.25f)
				}));
				list2.Add(new Outfit("Rule", 19, new List<OutfitModStat>
				{
					new OutfitModStat(OutfitModStat.OutfitModType.Damage, 0f, 0.1f),
					new OutfitModStat(OutfitModStat.OutfitModType.Armor, 0.1f)
				}));
				list2.Add(new Outfit(lvlStr, 7, new List<OutfitModStat>
				{
					new OutfitModStat(OutfitModStat.OutfitModType.Health, 0f, -0.5f),
					new OutfitModStat(OutfitModStat.OutfitModType.Damage, 0f, -0.5f),
					new OutfitModStat(OutfitModStat.OutfitModType.ODRate, 0f, -0.5f)
				}, isUnlocked: false, isLeveling: true));
				list2.Add(new Outfit("Venture", 2, new List<OutfitModStat>
				{
					new OutfitModStat(OutfitModStat.OutfitModType.Health, 0f, -0.4f),
					new OutfitModStat(OutfitModStat.OutfitModType.Damage, 0f, 0.1f),
					new OutfitModStat(OutfitModStat.OutfitModType.Speed, 0f, 0.1f),
					new OutfitModStat(OutfitModStat.OutfitModType.Cooldown, 0f, -0.1f)
				}));
				list2.Add(new Outfit("Fall", 9, new List<OutfitModStat>
				{
					new OutfitModStat(OutfitModStat.OutfitModType.Health, 0f, 0f, 100f),
					new OutfitModStat(OutfitModStat.OutfitModType.Fall, 0f, 0f, 0f, boolValue: true),
					new OutfitModStat(OutfitModStat.OutfitModType.AllowUpgrade)
				}));
				list2.Add(new Outfit("Pride", 15, new List<OutfitModStat>
				{
					new OutfitModStat(OutfitModStat.OutfitModType.Health, 0f, 0f, 1f),
					new OutfitModStat(OutfitModStat.OutfitModType.Pride, 0f, 0f, -1f),
					new OutfitModStat(OutfitModStat.OutfitModType.AllowUpgrade)
				}));
				list = (outfitList = list2);
			}
			return list;
		}
	}

	public Outfit(string newID, int newColorIndex, List<OutfitModStat> newModList, bool isUnlocked = false, bool isLeveling = false)
	{
		outfitID = newID;
		outfitColorIndex = newColorIndex;
		modList = newModList;
		unlocked = isUnlocked;
		useLeveling = isLeveling;
	}

	public Outfit(Outfit givenOutfit)
	{
		outfitID = givenOutfit.outfitID;
		outfitColorIndex = givenOutfit.outfitColorIndex;
		modList = new List<OutfitModStat>();
		for (int i = 0; i < givenOutfit.modList.Count; i++)
		{
			modList.Add(new OutfitModStat(givenOutfit.modList[i]));
		}
		unlocked = givenOutfit.unlocked;
	}

	public void SetEquipStatus(Player p, bool status)
	{
		parentPlayer = p;
		if (useLeveling)
		{
			lvlModList.Clear();
			levelModStat.Reset();
			Player player = parentPlayer;
			player.absEnemyKillEventHandlers = (Player.AbsEnemyKillEventHandler)Delegate.Remove(player.absEnemyKillEventHandlers, new Player.AbsEnemyKillEventHandler(OnEnemyDefeat));
			if (status)
			{
				Player player2 = parentPlayer;
				player2.absEnemyKillEventHandlers = (Player.AbsEnemyKillEventHandler)Delegate.Combine(player2.absEnemyKillEventHandlers, new Player.AbsEnemyKillEventHandler(OnEnemyDefeat));
				for (int i = 0; i < modList.Count; i++)
				{
					if (modList[i].hasAddValue)
					{
						modList[i].addModifier.modValue = 0f - levelModStat.CurrentValue;
						lvlModList.Add(modList[i].addModifier);
					}
					if (modList[i].hasMultiValue)
					{
						modList[i].multiModifier.modValue = 0f - levelModStat.CurrentValue;
						lvlModList.Add(modList[i].multiModifier);
					}
				}
			}
		}
		SetMods(status, OnEquip: true);
		if (!status)
		{
			parentPlayer = null;
		}
	}

	public void SetMods(bool status, bool OnEquip)
	{
		for (int i = 0; i < modList.Count; i++)
		{
			modList[i].SetModStatus(parentPlayer, status, OnEquip);
		}
	}

	public string GetDescription(bool addExtra = false)
	{
		description = string.Empty;
		if (modList != null)
		{
			foreach (OutfitModStat mod in modList)
			{
				description = description + mod.GetDescription(addExtra) + "\n";
			}
		}
		return description;
	}

	public void OnEnemyDefeat(Entity givenEnt, AttackInfo givenInfo)
	{
		Enemy enemy = givenEnt as Enemy;
		if (enemy == null || enemy is Blob || enemy.summoned || enemy.parentSummoner != null)
		{
			return;
		}
		for (int i = 0; i < lvlModList.Count; i++)
		{
			currentMod = lvlModList[i];
			if (currentMod != null)
			{
				currentMod.modValue = Mathf.Clamp(currentMod.modValue + levelModInc, 0f - levelModStat.CurrentValue, levelModStat.CurrentValue);
			}
		}
		SetMods(status: true, OnEquip: false);
	}

	public static void UpdateOutfitDictData()
	{
		outfitDict = new Dictionary<string, Outfit>();
		foreach (Outfit outfit in OutfitList)
		{
			outfitDict.Add(outfit.outfitID, outfit);
		}
		if (GameDataManager.gameData != null)
		{
			GameDataManager.gameData.PullOutfitData();
		}
		UpdateStarterOutfits(Application.loadedLevelName);
	}

	public static Outfit GetAvailableOutfit(string givenID)
	{
		return (!OutfitIsAvailable(givenID)) ? null : OutfitDict[givenID];
	}

	public static bool OutfitExists(string givenID)
	{
		return OutfitDict.ContainsKey(givenID);
	}

	public static bool OutfitIsAvailable(string givenID)
	{
		return OutfitDict.ContainsKey(givenID) && OutfitDict[givenID].unlocked;
	}

	public static bool OutfitIsInUse(string givenID, int givenPlayerID)
	{
		Player[] activePlayers = GameController.activePlayers;
		foreach (Player player in activePlayers)
		{
			if (!(player == null) && player.playerID != givenPlayerID && GameDataManager.gameData.playerData[player.playerID].outfitName == givenID)
			{
				return true;
			}
		}
		return false;
	}

	public static void UnlockOutfit(string givenName, bool pushData = true)
	{
		if (OutfitDict.ContainsKey(givenName))
		{
			OutfitDict[givenName].unlocked = true;
			if (pushData)
			{
				GameDataManager.gameData.PushOutfitData();
			}
		}
	}

	public static void SetNormal()
	{
		OutfitDict[normalID] = normalOutfit;
	}

	public static void HandleNOutfit(string givenID)
	{
		if (givenID == normalID || !OutfitIsAvailable(givenID))
		{
			return;
		}
		normalOutfit.useLeveling = givenID == lvlStr;
		normalOutfit.modList.Clear();
		foreach (OutfitModStat mod in GetAvailableOutfit(givenID).modList)
		{
			normalOutfit.modList.Add(new OutfitModStat(mod));
		}
		OutfitDict[normalID] = normalOutfit;
	}

	public static void UpdateStarterOutfits(string levelName)
	{
		if (levelName != "Tutorial" && levelName != "Epilogue" && !levelName.Contains("PvP") && OutfitDict["Vigor"].unlocked && OutfitDict["Venture"].unlocked)
		{
			if (OutfitDict["Pace"].unlocked && OutfitDict["Awe"].unlocked && OutfitDict["Rule"].unlocked)
			{
				OutfitDict["Hope"] = enhancedHope;
			}
			if (OutfitDict["Grit"].unlocked && OutfitDict["Switch"].unlocked && OutfitDict["Tempo"].unlocked)
			{
				OutfitDict["Patience"] = enhancedPatience;
			}
		}
		else
		{
			OutfitDict["Hope"] = baseHope;
			OutfitDict["Patience"] = basePatience;
		}
		if (normalOutfit != null && OutfitDict.ContainsKey(normalID))
		{
			normalOutfit.unlocked = OutfitDict[normalID].unlocked;
			OutfitDict[normalID] = normalOutfit;
		}
	}
}
using System.Collections.Generic;
using UnityEngine;

public class OutfitModStat
{
	public enum OutfitModType
	{
		None,
		Health,
		Speed,
		Run,
		Evade,
		Armor,
		CritChance,
		CritDamage,
		Damage,
		Cooldown,
		Pride,
		Fall,
		ODRate,
		ODDamage,
		HealAmount,
		HealCrit,
		Gold,
		Platinum,
		AllowUpgrade
	}

	public OutfitModType modType;

	protected string modIDPrefix = "OutfitModifier";

	protected string modifierID = string.Empty;

	protected string statDescription = string.Empty;

	protected string statDataFieldKey = string.Empty;

	protected bool updateValue;

	protected bool isIncrease;

	public bool hasAddValue;

	public NumVarStatMod addModifier;

	public bool hasMultiValue;

	public NumVarStatMod multiModifier;

	public bool hasOverrideValue;

	public NumVarStatMod overrideModifier;

	private BoolVarStatMod boolModifier;

	protected List<NumVarStat> targetNumVarStatList;

	protected List<BoolVarStat> targetBoolVarStatList;

	public OutfitModStat(OutfitModType givenType = OutfitModType.None, float addValue = 0f, float multiValue = 0f, float overrideValue = 0f, bool boolValue = false)
	{
		Initialize(givenType, addValue, multiValue, overrideValue, boolValue);
	}

	public OutfitModStat(OutfitModStat givenOM)
	{
		Initialize(givenOM.modType, givenOM.addModifier.modValue, givenOM.multiModifier.modValue, givenOM.overrideModifier.modValue, givenOM.boolModifier.modValue);
	}

	private void Initialize(OutfitModType givenType, float givenAdd, float givenMulti, float givenOver, bool givenBool)
	{
		modType = givenType;
		SetInitialVars();
		isIncrease = givenAdd + givenMulti > 0f;
		hasAddValue = givenAdd != 0f;
		hasMultiValue = givenMulti != 0f;
		hasOverrideValue = givenOver != 0f;
		addModifier = new NumVarStatMod(modIDPrefix + "Add" + modifierID, givenAdd);
		multiModifier = new NumVarStatMod(modIDPrefix + "Multi" + modifierID, givenMulti, 10, VarStatModType.Multiplicative);
		overrideModifier = new NumVarStatMod(modIDPrefix + "Override" + modifierID, givenOver, 1, VarStatModType.Override);
		targetNumVarStatList = new List<NumVarStat>();
		boolModifier = new BoolVarStatMod(modIDPrefix + "Bool" + modifierID, givenBool);
		targetBoolVarStatList = new List<BoolVarStat>();
	}

	private void SetInitialVars()
	{
		switch (modType)
		{
		case OutfitModType.Health:
			modifierID = "Health";
			statDescription = "wardrobeUI-statHealth";
			updateValue = true;
			break;
		case OutfitModType.Speed:
			modifierID = "MoveSpeed";
			statDescription = "wardrobeUI-statSpeed";
			break;
		case OutfitModType.Run:
			modifierID = "RunTime";
			statDescription = "wardrobeUI-statRun";
			break;
		case OutfitModType.Evade:
			modifierID = "Evade";
			statDescription = "wardrobeUI-statEvade";
			break;
		case OutfitModType.Armor:
			modifierID = "Armor";
			statDescription = "wardrobeUI-statArmor";
			break;
		case OutfitModType.CritChance:
			modifierID = "CritChance";
			statDescription = "wardrobeUI-statCritChance";
			statDataFieldKey = StatData.critChStr;
			break;
		case OutfitModType.CritDamage:
			modifierID = "CritDamage";
			statDescription = "wardrobeUI-statCritDamage";
			statDataFieldKey = StatData.critDmgStr;
			break;
		case OutfitModType.Damage:
			modifierID = "Damage";
			statDescription = "wardrobeUI-statDamage";
			statDataFieldKey = StatData.damageStr;
			break;
		case OutfitModType.Cooldown:
			modifierID = "Cooldown";
			statDescription = "wardrobeUI-statCooldown";
			statDataFieldKey = StatData.cdStr;
			break;
		case OutfitModType.ODRate:
			modifierID = "ODRate";
			statDescription = "wardrobeUI-statODRate";
			statDataFieldKey = StatData.odProgStr;
			break;
		case OutfitModType.ODDamage:
			modifierID = "ODDamage";
			statDescription = "wardrobeUI-statODDamage";
			statDataFieldKey = StatData.odDmgStr;
			break;
		case OutfitModType.HealAmount:
			modifierID = "HealAmount";
			statDescription = "wardrobeUI-statHealAmount";
			break;
		case OutfitModType.HealCrit:
			modifierID = "HealCrit";
			statDescription = "wardrobeUI-statHealCrit";
			break;
		case OutfitModType.Gold:
			modifierID = "Gold";
			statDescription = "wardrobeUI-gold";
			break;
		case OutfitModType.Platinum:
			modifierID = "Platinum";
			statDescription = "wardrobeUI-platinum";
			break;
		default:
			modifierID = string.Empty;
			statDescription = string.Empty;
			statDataFieldKey = string.Empty;
			updateValue = false;
			break;
		}
	}

	private void SetTargetVarStatList(Player p)
	{
		if (targetNumVarStatList != null)
		{
			targetNumVarStatList.Clear();
		}
		if (targetBoolVarStatList != null)
		{
			targetBoolVarStatList.Clear();
		}
		switch (modType)
		{
		case OutfitModType.Health:
			targetNumVarStatList.Add(p.health.healthStat);
			return;
		case OutfitModType.Speed:
			targetNumVarStatList.Add(p.movement.moveSpeedStat);
			return;
		case OutfitModType.Run:
			targetNumVarStatList.Add(p.runSpeedupStat);
			return;
		case OutfitModType.Evade:
			targetNumVarStatList.Add(p.health.evadeStat);
			return;
		case OutfitModType.Armor:
			targetNumVarStatList.Add(p.health.armorStat);
			return;
		case OutfitModType.Pride:
			targetNumVarStatList.Add(p.health.shieldStat);
			return;
		case OutfitModType.Fall:
			targetBoolVarStatList.Add(p.healthRegenStat);
			return;
		case OutfitModType.AllowUpgrade:
			targetBoolVarStatList.Add(p.outfitEnhanceAllowStat);
			return;
		case OutfitModType.HealAmount:
			targetNumVarStatList.Add(p.health.healModifierStat);
			return;
		case OutfitModType.HealCrit:
			targetNumVarStatList.Add(p.health.critHealModStat);
			return;
		case OutfitModType.Gold:
			targetNumVarStatList.Add(LootManager.globalGoldModifier);
			return;
		case OutfitModType.Platinum:
			targetNumVarStatList.Add(LootManager.globalPlatModifier);
			return;
		}
		if (!(statDataFieldKey != string.Empty))
		{
			return;
		}
		List<StatData> allStatData = StatManager.GetAllStatData("Skills", p.skillCategory);
		int count = allStatData.Count;
		for (int i = 0; i < count; i++)
		{
			if (!allStatData[i].GetValue<bool>("isStatusEffect"))
			{
				allStatData[i].EnsureVarStatEntry(statDataFieldKey);
				targetNumVarStatList.Add(allStatData[i].numVarStatDict[statDataFieldKey]);
			}
		}
	}

	public virtual void SetModStatus(Player givenPlayer, bool givenStatus, bool allowUpdate = true)
	{
		if (givenPlayer == null)
		{
			return;
		}
		isIncrease = addModifier.modValue + multiModifier.modValue > 0f;
		SetTargetVarStatList(givenPlayer);
		if (targetNumVarStatList != null && targetNumVarStatList.Count > 0)
		{
			int count = targetNumVarStatList.Count;
			if (givenStatus)
			{
				for (int i = 0; i < count; i++)
				{
					NumVarStat numVarStat = targetNumVarStatList[i];
					if (hasAddValue)
					{
						numVarStat.AddMod(addModifier);
					}
					if (hasMultiValue)
					{
						numVarStat.AddMod(multiModifier);
					}
					if (hasOverrideValue)
					{
						numVarStat.AddMod(overrideModifier);
					}
					if (updateValue && allowUpdate)
					{
						numVarStat.CurrentValue = numVarStat.ModifiedValue;
					}
				}
			}
			else
			{
				for (int j = 0; j < count; j++)
				{
					NumVarStat numVarStat = targetNumVarStatList[j];
					if (hasAddValue)
					{
						numVarStat.RemoveMod(addModifier.ID);
					}
					if (hasMultiValue)
					{
						numVarStat.RemoveMod(multiModifier.ID);
					}
					if (hasOverrideValue)
					{
						numVarStat.RemoveMod(overrideModifier.ID);
					}
					if (updateValue && allowUpdate)
					{
						numVarStat.CurrentValue = numVarStat.ModifiedValue;
					}
				}
			}
		}
		if (targetBoolVarStatList != null && targetBoolVarStatList.Count > 0)
		{
			int count = targetBoolVarStatList.Count;
			for (int k = 0; k < count; k++)
			{
				targetBoolVarStatList[k].Modify(boolModifier, givenStatus);
			}
		}
	}

	public virtual string GetDescription(bool addExtra = false)
	{
		return modType switch
		{
			OutfitModType.Platinum => TextManager.GetUIText("wardrobeUI-platinum") + (addExtra ? (" <color=#009999>( </color><color=#00dddd> + " + Mathf.FloorToInt(addModifier.modValue) + " </color><color=#009999> )</color>") : string.Empty), 
			OutfitModType.Gold => TextManager.GetUIText("wardrobeUI-gold") + (addExtra ? (" <color=#009999>( </color><color=#00dddd>" + Globals.PercentToStr(multiModifier, "+") + "</color><color=#009999> )</color>") : string.Empty), 
			OutfitModType.Pride => TextManager.GetUIText("wardrobeUI-statPride"), 
			OutfitModType.Fall => TextManager.GetUIText("wardrobeUI-statFall"), 
			OutfitModType.None => TextManager.GetUIText("wardrobeUI-statNone"), 
			OutfitModType.AllowUpgrade => string.Empty, 
			_ => ((!isIncrease) ? TextManager.GetUIText("wardrobeUI-decreaseStat") : TextManager.GetUIText("wardrobeUI-increaseStat")) + TextManager.GetUIText(statDescription) + ((!addExtra) ? string.Empty : (" <color=#009999>( </color><color=#00dddd>" + (hasAddValue ? Globals.PercentToStr(addModifier, (!isIncrease) ? "-" : "+") : (hasMultiValue ? Globals.PercentToStr(multiModifier, (!isIncrease) ? "-" : "+") : ((!hasOverrideValue) ? string.Empty : ((int)overrideModifier.modValue/*cast due to constrained. prefix*/).ToString()))) + "</color><color=#009999> )</color>")), 
		};
	}
}
using UnityEngine;

public class OutfitStoreItem : StoreItem
{
	private static GameObject prefab;

	public Sprite soldOutSprite;

	public Sprite mannequinSprite;

	public static bool wardSpawned;

	public OutfitMerchantNpc outfitMerchant;

	[HideInInspector]
	public string outfitID;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Items/OutfitStoreItem.prefab"));

	public override void Awake()
	{
		base.Awake();
		wardSpawned = false;
	}

	public override void Start()
	{
		base.Start();
		overheadPromptHeight = 2.75f;
		if (Outfit.OutfitDict.ContainsKey(outfitID))
		{
			itemSpriteRenderer.material.SetFloat("_PaletteIndex", Outfit.OutfitDict[outfitID].outfitColorIndex);
			itemText.text = TextManager.GetOutfitName(outfitID);
			descText.text = Outfit.OutfitDict[outfitID].GetDescription();
		}
		else
		{
			itemText.text = string.Empty;
			Sellout();
		}
	}

	public void Sellout()
	{
		priceMarker.SetText("x");
		itemBGSpriteRenderer.sprite = soldOutSprite;
		Object.Destroy(itemSpriteRenderer.gameObject);
		Object.Destroy(promptTrigger.gameObject);
		if (outfitMerchant != null)
		{
			outfitMerchant.availableOutfitCount--;
			outfitMerchant.outfitsOnSaleCount--;
			if (outfitMerchant.availableOutfitCount <= 0)
			{
				outfitMerchant.noOutfitsAvailable = true;
			}
		}
		Object.Destroy(this);
	}

	public override bool Buy(Player player)
	{
		if (Player.platWallet == null)
		{
			return false;
		}
		if (Player.platWallet.balance < Cost)
		{
			SoundManager.PlayAudio("MenuError");
			if (parentNpc != null)
			{
				parentNpc.PlayEmote(EmoteType.No);
			}
			return false;
		}
		SoundManager.PlayAudio("MenuBuy");
		Player.platWallet.Withdraw(Cost);
		Outfit.UnlockOutfit(outfitID);
		GameDataManager.Save();
		GameController.unlockNotifier.Notify(outfitID, UnlockNotifier.NoticeType.Outfit);
		AchievementManager.UnlockAchievement(Achievement.UnlockAllOutfits);
		CurrentOverheadPrompt = null;
		ToggleItemInfo(status: false);
		Sellout();
		if (!wardSpawned)
		{
			wardSpawned = true;
			SpawnWard();
		}
		return true;
	}

	public static void SpawnWard()
	{
		Vector2 vector = new Vector2(21.75f, 27.5f);
		PoolManager.GetPoolItem<AnimEffect>("TeleportEffect").Play(vector, string.Empty);
		Globals.ChaosInst<WardrobeNpc>(WardrobeNpc.Prefab, null, vector);
		Attack attack = Globals.ChaosInst<Attack>(Attack.CirclePrefab, null, vector);
		attack.SetAttackInfo("Player", Player.ShootFireball.staticID);
		attack.transform.localScale = Vector3.one * 2f;
		Object.Destroy(attack.gameObject, 0.25f);
	}
}

using System;
using System.Collections.Generic;
using UnityEngine;

public class OutfitMerchantNpc : Npc
{
	private bool wardrobeUnlocked;

	public bool noOutfitsAvailable;

	private static bool[] playerBuffed = new bool[GameController.maxPlayerCount];

	public int outfitsOnSaleCount = 3;

	public int availableOutfitCount;

	private List<string> lockedOutfitIDList = new List<string>();

	private Vector2 spawnOrigin = Vector2.zero;

	private Vector2[] spawnPositions = new Vector2[3]
	{
		new Vector2(-2f, 0f),
		new Vector2(0f, 0f),
		new Vector2(2f, 0f)
	};

	private int cost = 5;

	private int endDialogIndex = 4;

	private List<string> bossNameList = new List<string> { "EarthBoss", "FireBoss", "IceBoss", "AirBoss", "LightningBoss" };

	public override void Awake()
	{
		base.Awake();
		Transform transform = base.transform.Find("OutfitSpawnLocation");
		if (transform != null)
		{
			spawnOrigin = transform.position;
		}
	}

	public override void Start()
	{
		base.Start();
		wardrobeUnlocked = GameDataManager.gameData.CheckNPCStatus("Ward");
		overheadPromptHeight = 3f;
		if (wardrobeUnlocked)
		{
			LoadOutfitItems();
		}
		Player.playerDestroyEventHandlers = (Player.PlayerEventHandler)Delegate.Remove(Player.playerDestroyEventHandlers, new Player.PlayerEventHandler(PlayerDestroyEvent));
		Player.playerDestroyEventHandlers = (Player.PlayerEventHandler)Delegate.Combine(Player.playerDestroyEventHandlers, new Player.PlayerEventHandler(PlayerDestroyEvent));
		Player.outfitEquipEventHandlers = (Player.OutfitEquipEventHandler)Delegate.Remove(Player.outfitEquipEventHandlers, new Player.OutfitEquipEventHandler(PlayerOutfitEquipEvent));
		Player.outfitEquipEventHandlers = (Player.OutfitEquipEventHandler)Delegate.Combine(Player.outfitEquipEventHandlers, new Player.OutfitEquipEventHandler(PlayerOutfitEquipEvent));
	}

	public static void PlayerDestroyEvent(Player player)
	{
		playerBuffed[player.playerID] = false;
	}

	public static void PlayerOutfitEquipEvent(Player player, string outfitID)
	{
		if (playerBuffed[player.playerID])
		{
			playerBuffed[player.playerID] = false;
			Outfit.SavileOutfit.SetEquipStatus(player, status: false);
		}
	}

	public override bool HandleConditionalInteraction()
	{
		if (myDialogID != "OutfitMerchant-Hub")
		{
			return false;
		}
		if (playerBuffed[player.playerID] && CurrentDialogIndex < endDialogIndex)
		{
			CurrentDialogIndex = endDialogIndex;
			return false;
		}
		switch (CurrentDialogIndex)
		{
		case 0:
			if (!player.outfitEnhanceAllowStat.CurrentValue)
			{
				CurrentDialogIndex = 6;
				return false;
			}
			break;
		case 2:
			if (Player.platWallet.balance >= cost)
			{
				CurrentDialogIndex = 3;
			}
			break;
		case 3:
			playerLeavingDialog = true;
			return true;
		case 4:
			playerBuffed[player.playerID] = true;
			Player.platWallet.Withdraw(cost);
			SoundManager.PlayAudio("MenuBuy");
			SoundManager.PlayAudio("Tailor0");
			Outfit.SavileOutfit.outfitColorIndex = player.outfitColorIndex;
			Outfit.GetAvailableOutfit(player.outfitID).SetEquipStatus(player, status: false);
			Outfit.SavileOutfit.SetEquipStatus(player, status: true);
			player.equippedOutfit = Outfit.SavileOutfit;
			PoolManager.GetPoolItem<ParticleEffect>("SparkleAura").Emit(13, player.transform.position + Vector3.up * 0.25f);
			GameDataManager.Save();
			break;
		case 6:
			playerLeavingDialog = true;
			return true;
		}
		return false;
	}

	private void LoadOutfitItems()
	{
		lockedOutfitIDList.Clear();
		Outfit.UpdateOutfitDictData();
		foreach (Outfit outfit in Outfit.OutfitList)
		{
			if (outfit != null && !outfit.unlocked)
			{
				lockedOutfitIDList.Add(outfit.outfitID);
			}
		}
		availableOutfitCount = lockedOutfitIDList.Count;
		noOutfitsAvailable = availableOutfitCount == 0;
		int num = 0;
		for (int i = 0; i < availableOutfitCount; i++)
		{
			if (num >= outfitsOnSaleCount)
			{
				break;
			}
			if (ConditionalRequirementMet(lockedOutfitIDList[i]))
			{
				CreateOutfitStoreItem(spawnPositions[num] + spawnOrigin, lockedOutfitIDList[i]);
				num++;
			}
		}
		for (int j = num; j < outfitsOnSaleCount; j++)
		{
			CreateOutfitStoreItem(spawnPositions[j] + spawnOrigin, string.Empty);
		}
	}

	private void CreateOutfitStoreItem(Vector2 givenPosition, string givenID)
	{
		OutfitStoreItem outfitStoreItem = Globals.ChaosInst<OutfitStoreItem>(OutfitStoreItem.Prefab, transform, givenPosition);
		outfitStoreItem.outfitID = givenID;
		outfitStoreItem.outfitMerchant = this;
		outfitStoreItem.parentNpc = this;
		outfitStoreItem.usePlatinumCost = true;
	}

	private bool ConditionalRequirementMet(string givenName)
	{
		if (GameDataManager.gameData == null || GameDataManager.gameData.gameStats == null)
		{
			return true;
		}
		switch (givenName)
		{
		case "Venture":
			foreach (string bossName in bossNameList)
			{
				if (GameDataManager.gameData.gameStats.GetEnemyDefeatedCount(bossName) > 0)
				{
					return true;
				}
			}
			return false;
		case "Fall":
			return GameDataManager.GameCleared;
		case "Pride":
			return GameDataManager.GameCleared;
		case "Level":
			return GameDataManager.GameCleared;
		default:
			return true;
		}
	}
}
using System;
using UnityEngine;

public class TailorNpc : Npc
{
	private static GameObject sparklePrefab;

	private static bool[] playerBuffed = new bool[GameController.maxPlayerCount];

	private static int goldCost = 100;

	private static int healthCost = 100;

	private Outfit currentOutfit;

	private OutfitModStat currentMod;

	private int currentHealth;

	private static float upgradeValue = 1.5f;

	public static GameObject SparklePrefab => sparklePrefab ?? (sparklePrefab = ChaosBundle.Get("Assets/Prefabs/Effects/OutfitSparkle.prefab"));

	public override void Start()
	{
		base.Start();
		overheadPromptHeight = 3f;
		CompassIndicatorTrigger.Spawn(Compass.CompassIndicatorType.TailorRoom, transform.position, transform);
		Player.playerDestroyEventHandlers = (Player.PlayerEventHandler)Delegate.Remove(Player.playerDestroyEventHandlers, new Player.PlayerEventHandler(PlayerDestroyEvent));
		Player.playerDestroyEventHandlers = (Player.PlayerEventHandler)Delegate.Combine(Player.playerDestroyEventHandlers, new Player.PlayerEventHandler(PlayerDestroyEvent));
		Player.outfitEquipEventHandlers = (Player.OutfitEquipEventHandler)Delegate.Remove(Player.outfitEquipEventHandlers, new Player.OutfitEquipEventHandler(PlayerOutfitEquipEvent));
		Player.outfitEquipEventHandlers = (Player.OutfitEquipEventHandler)Delegate.Combine(Player.outfitEquipEventHandlers, new Player.OutfitEquipEventHandler(PlayerOutfitEquipEvent));
	}

	public static void PlayerDestroyEvent(Player player)
	{
		playerBuffed[player.playerID] = false;
	}

	public static void PlayerOutfitEquipEvent(Player player, string outfitID)
	{
		playerBuffed[player.playerID] = false;
	}

	public override bool HandleConditionalInteraction()
	{
		switch (CurrentDialogIndex)
		{
		case 0:
			if (playerBuffed[player.playerID])
			{
				CurrentDialogIndex = 4;
			}
			else if (!player.outfitEnhanceAllowStat.CurrentValue)
			{
				CurrentDialogIndex = 6;
			}
			break;
		case 1:
			if (!player.inventory.ContainsItem("TokenTailor"))
			{
				CurrentDialogIndex = 2;
			}
			break;
		case 2:
			if (player.inventory.ContainsItem("TokenTailor"))
			{
				HandleUpgradeOutfit(useToken: true);
				CurrentDialogIndex = 4;
			}
			else
			{
				CurrentDialogIndex = 3;
			}
			break;
		case 3:
			if (Player.goldWallet.balance < goldCost)
			{
				CurrentDialogIndex = 5;
			}
			break;
		case 4:
			HandleUpgradeOutfit();
			break;
		case 5:
			playerLeavingDialog = true;
			return true;
		case 6:
			playerLeavingDialog = true;
			return true;
		}
		return false;
	}

	private void HandleUpgradeOutfit(bool useToken = false)
	{
		if (playerBuffed[player.playerID])
		{
			CurrentDialogIndex = 4;
			return;
		}
		playerBuffed[player.playerID] = true;
		currentHealth = player.health.CurrentHealthValue + ((!useToken) ? (-healthCost) : 0);
		PoolManager.GetPoolItem<ParticleEffect>("SparkleAura").Emit(15, player.transform.position + Vector3.up * 0.25f);
		SoundManager.PlayAudio("MenuBuy");
		SoundManager.PlayAudio("Tailor0");
		UpgradePlayerOutfit();
		if (useToken)
		{
			player.inventory.RemoveItem("TokenTailor", forceOverride: false, showNotice: true);
		}
		else
		{
			Player.goldWallet.Withdraw(goldCost);
		}
		player.health.CurrentHealthValue = Mathf.Max(1, currentHealth);
		RunData.miscTailorRoomFound = true;
	}

	private void UpgradePlayerOutfit()
	{
		if (Outfit.GetAvailableOutfit(player.outfitID) == null)
		{
			return;
		}
		if (player.equippedOutfit.useLeveling)
		{
			player.equippedOutfit.levelModStat.AddMod(new NumVarStatMod("TailorNPC", upgradeValue - 1f, 10, VarStatModType.Multiplicative));
			RunData.prdDict[player.playerID].outFitEnhanced = true;
			player.outfitEnhanced = true;
			Globals.ChaosInst<Transform>(SparklePrefab, player.attackOriginTrans, player.attackOriginTrans.position);
			return;
		}
		currentOutfit = new Outfit(Outfit.GetAvailableOutfit(player.outfitID));
		Outfit.GetAvailableOutfit(player.outfitID).SetEquipStatus(player, status: false);
		if (currentOutfit.outfitID == "Hope" && currentOutfit.modList.Count <= 1)
		{
			currentOutfit = Outfit.enhancedHope;
		}
		else if (currentOutfit.outfitID == "Patience" && currentOutfit.modList.Count <= 1)
		{
			currentOutfit = Outfit.enhancedPatience;
		}
		else
		{
			foreach (OutfitModStat mod in currentOutfit.modList)
			{
				currentMod = mod;
				if (currentMod == null)
				{
					continue;
				}
				if (currentMod.modType == OutfitModStat.OutfitModType.Health)
				{
					if (currentMod.addModifier.modValue > 0f)
					{
						currentMod.addModifier.modValue *= upgradeValue;
					}
					if (currentMod.multiModifier.modValue > 0f)
					{
						currentMod.multiModifier.modValue *= upgradeValue;
					}
				}
				else
				{
					currentMod.addModifier.modValue *= upgradeValue;
					currentMod.multiModifier.modValue *= upgradeValue;
					currentMod.overrideModifier.modValue *= upgradeValue;
				}
			}
		}
		currentOutfit.SetEquipStatus(player, status: true);
		player.equippedOutfit = currentOutfit;
		player.outfitEnhanced = true;
		if (RunData.prdDict.ContainsKey(player.playerID) && RunData.prdDict[player.playerID] != null)
		{
			RunData.prdDict[player.playerID].outFitEnhanced = true;
		}
		Globals.ChaosInst<Transform>(SparklePrefab, player.attackOriginTrans, player.attackOriginTrans.position);
	}
}
using Chaos.AnimatorExtensions;
using Chaos.ArrayExtensions;
using UnityEngine;

public class WardrobeNpc : Npc
{
	private static GameObject prefab;

	private bool closeAnimPlayed = true;

	private int idleAnimTimer = -1;

	private float idleAnimTime = 1f;

	private float minIdleAnimTime = 2f;

	private float maxIdleAnimTime = 5f;

	private string[] idleAnimNames = new string[2] { "Mustache", "Blink" };

	private bool dialogCompleted;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Allies/WardrobeNpc.prefab"));

	public override void Start()
	{
		base.Start();
		overheadPromptHeight = 4f;
	}

	public override void Interacted()
	{
		if (dialogCompleted || PlayerRoomUI.CurrentUI.AnyUIOpen)
		{
			CurrentOverheadPrompt = null;
			Exiting();
			return;
		}
		if (!isSpeaking)
		{
			anim.Play("Bounce", -1, 0f);
		}
		base.Interacted();
	}

	public override void Exiting()
	{
		Player player = base.player;
		base.Exiting();
		if (myDialogID.EndsWith("Ending"))
		{
			return;
		}
		if (!PlayerRoomUI.CurrentUI.IsUsingWardrobe(player))
		{
			if (!PlayerRoomUI.CurrentUI.WardrobeIsOpen)
			{
				anim.Play("Open", -1, 0f);
			}
			PlayerRoomUI.CurrentUI.OpenWardrobe(player, transform.position);
			closeAnimPlayed = false;
		}
		dialogCompleted = true;
	}

	public override void Update()
	{
		HandleIdleAnim();
		if (!PlayerRoomUI.CurrentUI.WardrobeIsOpen && !closeAnimPlayed)
		{
			anim.Play("Close", -1, 0f);
			closeAnimPlayed = true;
		}
		if (!(player != null) || !PlayerRoomUI.CurrentUI.IsUsingWardrobe(player))
		{
			base.Update();
		}
	}

	public override void OnTriggerStay2D(Collider2D col)
	{
		if (col.gameObject.name == "AllyFloorContact")
		{
			Player component = col.transform.parent.gameObject.GetComponent<Player>();
			if (player == null && component != null && !PlayerRoomUI.CurrentUI.IsUsingWardrobe(component))
			{
				player = component;
				CurrentOverheadPrompt.Initialize(transform, player.inputDevice.inputScheme, overheadPromptHeight);
				CurrentOverheadPrompt.DisplayPrompt("Interact");
			}
		}
	}

	public void HandleIdleAnim()
	{
		if (!PlayerRoomUI.CurrentUI.WardrobeIsOpen && closeAnimPlayed && anim.AnimPlayed() && ChaosStopwatch.Check(idleAnimTimer))
		{
			anim.Play(idleAnimNames.GetRandomValue(), -1, 0f);
			idleAnimTimer = ChaosStopwatch.Begin(idleAnimTime);
			idleAnimTime = Random.Range(minIdleAnimTime, maxIdleAnimTime);
		}
	}
}
