public class OutfitMenu : MonoBehaviour
{
	public Player player;

	public LowerHUD parentHUD;

	private bool hasFocus;

	[HideInInspector]
	public EquipMenu equipMenu;

	[HideInInspector]
	public InventoryMenu inventoryMenu;

	[HideInInspector]
	public Text infoText;

	private Vector2 navVector;

	private bool inputReceived;

	private GameObject selectionObj;

	private Text outfitText;

	private Image outfitImage;

	private void Awake()
	{
		selectionObj = transform.Find("SelectionBorder").gameObject;
		outfitText = transform.Find("OutfitName").GetComponent<Text>();
		TextManager.AddUIRef(string.Empty, outfitText);
		outfitImage = transform.Find("OutfitIcon").GetComponent<Image>();
		outfitImage.material = new Material(outfitImage.material);
		selectionObj.SetActive(value: false);
		gameObject.SetActive(value: false);
	}

	private void Update()
	{
		if (!(player == null) && hasFocus)
		{
			HandleNavigation();
		}
	}

	private void HandleNavigation()
	{
		navVector = player.inputDevice.GetMoveVector();
		if (inputReceived && navVector.sqrMagnitude < 0.04f)
		{
			inputReceived = false;
		}
		else if (!inputReceived && navVector.y < 0f && navVector.sqrMagnitude > 0.09f)
		{
			inputReceived = true;
			SoundManager.PlayAudio("MenuMove");
			SwapFocus(givenStatus: false);
		}
	}

	private void SwapFocus(bool givenStatus)
	{
		SetFocus(givenStatus);
		equipMenu.SetFocus(!givenStatus);
		inventoryMenu.SetFocus(status: false);
	}

	public void LoadMenu(Player p)
	{
		player = p;
