	public bool EquipOutfit(string newOutfitID)
	{
		DialogManager.speakerDict[skillCategory] = new DialogSpeakerInfo(skillCategory, playerData.name, "#FFFFFF", portraitSpriteID: "Player", paletteIndex: outfitColorIndex, nameColor: null, fillColorHex: string.Empty, fillColor: null, borderSpriteID: "GrayPanelUnfilled", messageBoxColorHex: string.Empty);
		if (!Outfit.OutfitExists(newOutfitID) || newOutfitID == "default")
		{
			newOutfitID = ((playerID != 0) ? "Patience" : "Hope");
		}
		else if (Outfit.OutfitIsInUse(newOutfitID, playerID))
		{
			if (!Outfit.OutfitIsInUse("Hope", playerID))
			{
				newOutfitID = "Hope";
			}
			else if (!Outfit.OutfitIsInUse("Patience", playerID))
			{
				newOutfitID = "Patience";
			}
		}
		if (!Outfit.OutfitIsAvailable(newOutfitID))
		{
			return false;
		}
		if (outfitEquipEventHandlers != null)
		{
			outfitEquipEventHandlers(this, outfitID);
		}
		if (newOutfitID == Outfit.normalID)
		{
			Outfit.HandleNOutfit(outfitID);
		}
		if (Outfit.GetAvailableOutfit(outfitID) != null)
		{
			Outfit.GetAvailableOutfit(outfitID).SetEquipStatus(this, status: false);
		}
		Outfit.GetAvailableOutfit(newOutfitID).SetEquipStatus(this, status: true);
		equippedOutfit = Outfit.GetAvailableOutfit(newOutfitID);
		outfitID = newOutfitID;
		outfitColorMod.modValue = Outfit.GetAvailableOutfit(newOutfitID).outfitColorIndex;
		SetPlayerOutfitColor(outfitColorMod);
		if (outfitEquipActualEventHandlers != null)
		{
			outfitEquipActualEventHandlers(this, outfitID);
		}
		return true;
	}

