public class DoctorNpc : Npc
{
	public static List<string> itemList = new List<string>
	{
		DoctorDiscount.staticID,
		DoctorPrescription.staticID,
		DoctorPlacebo.staticID,
		DoctorVial.staticID,
		CritHealChanceUp.staticID,
		HealRestock.staticID,
		DoctorHpDamage.staticID
	};

	public static List<string> altList = new List<string>
	{
		DoctorPrescription.staticID,
		DoctorPlacebo.staticID,
		DoctorVial.staticID,
		CritHealChanceUp.staticID,
		HealRestock.staticID,
		DoctorHpDamage.staticID
	};

	private int healthDropCount = 3;

	private bool prescriptionWritten;

	public override void Start()
	{
		CompassIndicatorTrigger.Spawn(Compass.CompassIndicatorType.NurseRoom, transform.position, transform);
	}

	public override bool HandleConditionalInteraction()
	{
		switch (DialogManager.dialogDict[myDialogID].CurrentIndex)
		{
		case 0:
			if (prescriptionWritten)
			{
				DialogManager.dialogDict[myDialogID].CurrentIndex = 5;
			}
			SoundManager.PlayAudio("Doctor" + Random.Range(0, 3), Random.Range(0.85f, 0.95f));
			PoolManager.GetPoolItem<EmoteEmitter>().Emit(EmoteType.Hmm, 1, transform.position + Vector3.up * 3f);
			break;
		case 1:
			if (!prescriptionWritten && player != null && player.inventory.ContainsItem("TokenDoctor"))
			{
				DialogManager.dialogDict[myDialogID].CurrentIndex = 2;
			}
			break;
		case 2:
			if (!prescriptionWritten)
			{
				if (player != null && player.GetRandomStandardSkill() != null)
				{
					WritePrescription();
				}
				else
				{
					DialogManager.dialogDict[myDialogID].CurrentIndex = 3;
				}
			}
			break;
		case 3:
			if (!prescriptionWritten && player != null)
			{
				WritePrescription(useToken: true);
			}
			break;
		case 4:
			if (!prescriptionWritten)
			{
				playerLeavingDialog = true;
				return true;
			}
			break;
		case 5:
			if (prescriptionWritten)
			{
				playerLeavingDialog = true;
				return true;
			}
			break;
		}
		return false;
	}

	private void WritePrescription(bool useToken = false)
	{
		prescriptionWritten = true;
		DialogManager.dialogDict[myDialogID].CurrentIndex = 4;
		if (useToken)
		{
			player.inventory.RemoveItem("TokenDoctor", forceOverride: false, showNotice: true);
			LootManager.DropHealth(transform.position, healthDropCount + 2);
		}
		else
		{
			player.RemoveSkill(player.GetRandomStandardSkill(allowEmp: false) ?? player.GetRandomStandardSkill());
			LootManager.DropHealth(transform.position, healthDropCount);
		}
		RunData.miscNurseRoomFound = true;
		if (player.inventory.ContainsItem(DiscountGroupItem.staticID))
		{
			GroupItem groupItem = player.inventory.GetItem(DiscountGroupItem.staticID) as GroupItem;
			if (!groupItem.itemInven.ContainsItem(DoctorDiscount.staticID))
			{
				player.inventory.AddItem(DoctorDiscount.staticID, showNotice: true);
				return;
			}
			if (AddDoctorItemFromList(altList))
			{
				return;
			}
		}
		else if (AddDoctorItemFromList(itemList))
		{
			return;
		}
		DialogManager.dialogDict[myDialogID].CurrentIndex = 5;
	}

	private bool AddDoctorItemFromList(List<string> givenList)
	{
		if (givenList != null)
		{
			givenList.Shuffle();
			for (int i = 0; i < givenList.Count; i++)
			{
				if (!player.inventory.ContainsItem(givenList[i]))
				{
					player.inventory.AddItem(givenList[i], showNotice: true);
					return true;
				}
			}
		}
		return false;
	}
}

using System.Collections.Generic;
using Chaos.ListExtensions;
using UnityEngine;

public class RelicWell : MonoBehaviour
{
	public struct RelicInRange
	{
		public ItemDrop item;

		public Vector2 startPos;
	}

	public delegate void CollectRelicEventHandler(int givenCost);

	private static GameObject prefab;

	private Dictionary<RelicInRange, ChaosQuickStopwatch> relicTimers;

	private Dictionary<RelicInRange, float> relicRangeDuration;

	private List<RelicInRange> itemsInRange;

	private List<RelicInRange> itemsToRemove;

	private const float attractDelay = 1f;

	private const float attractTime = 1f;

	private Vector2 lootDropLocation;

	private float costModifier = 0.4f;

	private int goldValue;

	public CollectRelicEventHandler collectRelicEventHandler;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/RelicWell.prefab"));

	private void Start()
	{
		lootDropLocation = transform.position;
		itemsInRange = new List<RelicInRange>(20);
		itemsToRemove = new List<RelicInRange>(20);
		relicTimers = new Dictionary<RelicInRange, ChaosQuickStopwatch>(20);
		relicRangeDuration = new Dictionary<RelicInRange, float>(20);
	}

	public void Update()
	{
		if (itemsInRange.Count == 0)
		{
			return;
		}
		itemsInRange.RemoveNullValues();
		for (int i = 0; i < itemsInRange.Count; i++)
		{
			RelicInRange relicInRange = itemsInRange[i];
			if (relicRangeDuration[relicInRange] < 1f)
			{
				relicRangeDuration[relicInRange] += Time.deltaTime;
				continue;
			}
			if (!relicTimers[relicInRange].IsRunning)
			{
				relicTimers[relicInRange].IsRunning = true;
				continue;
			}
			if (Vector2.Distance(relicInRange.item.transform.position, transform.position) <= 1f)
			{
				CollectRelic(relicInRange.item);
				itemsToRemove.Add(relicInRange);
			}
			else
			{
				itemsInRange[i].item.rigidbody2D.MovePosition(Vector2.Lerp(itemsInRange[i].startPos, transform.position, Globals.GetSmoothLerpValue(relicTimers[relicInRange].TimePercentage)));
			}
			relicRangeDuration[relicInRange] += Time.deltaTime;
		}
		if (itemsToRemove.Count > 0)
		{
			for (int j = 0; j < itemsToRemove.Count; j++)
			{
				itemsInRange.Remove(itemsToRemove[j]);
				relicRangeDuration.Remove(itemsToRemove[j]);
				relicTimers.Remove(itemsToRemove[j]);
			}
			itemsToRemove.Clear();
		}
	}

	public void OnTriggerEnter2D(Collider2D col)
	{
		if (!(col.name != "ItemHitBox") && !(col.transform.parent == null))
		{
			ItemDrop component = col.transform.parent.GetComponent<ItemDrop>();
			if (!(component == null))
			{
				RelicInRange relicInRange = new RelicInRange
				{
					item = component,
					startPos = component.transform.position
				};
				itemsInRange.Add(relicInRange);
				relicRangeDuration[relicInRange] = 0f;
				relicTimers[relicInRange] = new ChaosQuickStopwatch();
			}
		}
	}

	private void CollectRelic(ItemDrop givenID)
	{
		if (!(givenID == null) && !(givenID.itemID == string.Empty))
		{
			goldValue = Mathf.CeilToInt((float)LootManager.GetPrice(givenID.itemID) * costModifier);
			if (givenID.itemID == "TokenCollector")
			{
				goldValue *= 3;
			}
			else if (Inventory.EitherPlayerHasItem("TokenCollector"))
			{
				goldValue *= 2;
			}
			LootManager.DropGold(lootDropLocation, goldValue);
			SoundManager.PlayAudio("MenuBuy");
			givenID.Disable();
			if (collectRelicEventHandler != null)
			{
				collectRelicEventHandler(goldValue);
			}
		}
	}
}
using System.Collections.Generic;
using UnityEngine;

public class SlotsNpc : Npc
{
	private enum RollType
	{
		Gold,
		Health,
		Skill,
		Item,
		Jackpot
	}

	private const int rollCount = 3;

	private int rollCounter;

	private RollType[] rollResults = new RollType[3];

	private SpriteRenderer[] rollSpriteRenderers = new SpriteRenderer[3];

	private string[] rollAnimNames = new string[3] { "Roll3", "Roll2", "Roll1" };

	private float[] rollDelay = new float[3] { 0.5f, 0.5f, 1f };

	private int rollStopwatchID;

	private int costToRoll = 25;

	private float chanceToMatchTwo = 0.5f;

	private bool matchTwo;

	private bool isRolling;

	private bool rollComplete;

	private float stopWaitTime = 1.25f;

	private List<RollType> rollTypeList = new List<RollType>
	{
		RollType.Gold,
		RollType.Health,
		RollType.Skill,
		RollType.Item,
		RollType.Jackpot
	};

	private int rollTypeListCount;

	public Sprite goldSprite;

	public Sprite healthSprite;

	public Sprite skillSprite;

	public Sprite itemSprite;

	public Sprite jackpotSprite;

	private Dictionary<RollType, Sprite> rollSpriteDict;

	private bool prizeWon;

	private RollType prizeType;

	private int dialogOverrideVal;

	public override void Awake()
	{
		base.Awake();
		for (int i = 0; i < 3; i++)
		{
			rollSpriteRenderers[i] = transform.Find("RollSprite" + i).GetComponent<SpriteRenderer>();
		}
		rollSpriteDict = new Dictionary<RollType, Sprite>
		{
			{
				RollType.Gold,
				goldSprite
			},
			{
				RollType.Health,
				healthSprite
			},
			{
				RollType.Skill,
				skillSprite
			},
			{
				RollType.Item,
				itemSprite
			},
			{
				RollType.Jackpot,
				jackpotSprite
			}
		};
	}

	public override void Start()
	{
		base.Start();
		rollTypeListCount = rollTypeList.Count;
	}

	public override void Update()
	{
		if (!isRolling || playerLeavingDialog)
		{
			base.Update();
		}
		if (!isRolling || !ChaosStopwatch.Check(rollStopwatchID))
		{
			return;
		}
		if (rollCounter >= 3)
		{
			if (!rollComplete)
			{
				rollComplete = true;
				rollStopwatchID = ChaosStopwatch.Begin(stopWaitTime);
				anim.Play("Stop");
				if (!DialogManager.dialogInProgress)
				{
					GameUI.dialogManager.DisplayDialog(myDialogID, dialogOverrideVal, string.Empty, string.Empty, string.Empty, isSign: true);
				}
				return;
			}
			isRolling = false;
			anim.Play("Idle");
			if (prizeWon)
			{
				SpawnReward(prizeType);
			}
			if (DialogManager.currentDialogID == myDialogID)
			{
				GameUI.dialogManager.ResetDialog(myDialogID);
				GameUI.dialogManager.Deactivate();
			}
		}
		else
		{
			rollStopwatchID = ChaosStopwatch.Begin((!matchTwo) ? 0.5f : rollDelay[rollCounter]);
			anim.Play(rollAnimNames[rollCounter]);
			rollSpriteRenderers[rollCounter].sprite = rollSpriteDict[rollResults[rollCounter]];
			rollCounter++;
		}
	}

	public override void InteractEvent()
	{
		anim.Play("Idle");
	}

	public override bool HandleConditionalInteraction()
	{
		switch (DialogManager.dialogDict[myDialogID].CurrentIndex)
		{
		case 1:
			if (Player.goldWallet.balance >= costToRoll)
			{
				Player.goldWallet.Withdraw(costToRoll);
				player.stats.ModifyValue(PlayerEndStats.Stat.Spent, costToRoll);
				SoundManager.PlayAudio("MenuBuy");
				InitRoll();
				playerLeavingDialog = true;
				RunData.miscSlotsRoomFound = true;
			}
			break;
		case 2:
			playerLeavingDialog = true;
			break;
		}
		return false;
	}

	public override void OnTriggerStay2D(Collider2D col)
	{
		if (!isRolling)
		{
			base.OnTriggerStay2D(col);
		}
	}

	public override void SpawnCompassTrigger()
	{
		CompassIndicatorTrigger.Spawn(Compass.CompassIndicatorType.SlotsRoom, transform.position, transform);
	}

	private void InitRoll()
	{
		rollCounter = 0;
		isRolling = true;
		rollComplete = false;
		SetRollResults();
	}

	private void SetRollResults()
	{
		for (int i = 0; i < 3; i++)
		{
			rollResults[i] = rollTypeList[Random.Range(0, rollTypeListCount)];
			rollSpriteRenderers[i].sprite = null;
		}
		if (Random.value < chanceToMatchTwo)
		{
			rollResults[1] = rollResults[0];
		}
		matchTwo = rollResults[1] == rollResults[0];
		prizeWon = rollResults[0] == rollResults[1] && rollResults[0] == rollResults[2];
		if (prizeWon)
		{
			prizeType = rollResults[0];
			dialogOverrideVal = 2;
		}
		else
		{
			ref int reference = ref dialogOverrideVal;
			int num;
			if (matchTwo)
			{
				num = ((!Globals.RandBool) ? 4 : 3);
			}
			else
			{
				num = ((!Globals.RandBool) ? 6 : 5);
			}
			reference = num;
		}
	}

	private void SpawnReward(RollType givenType)
	{
		Vector2 vector = transform.position;
		switch (givenType)
		{
		case RollType.Gold:
			LootManager.DropGold(vector, 300);
			break;
		case RollType.Health:
			LootManager.DropHealth(vector, 5);
			break;
		case RollType.Skill:
			LootManager.DropSkill(vector, 1, string.Empty, 0f, 0f, null, useLifeTime: false, isEmpowered: true);
			break;
		case RollType.Item:
			LootManager.DropItem(vector, 2, string.Empty);
			break;
		case RollType.Jackpot:
			LootManager.DropGold(vector, 100);
			LootManager.DropHealth(vector, 1);
			if (Globals.RandBool)
			{
				LootManager.DropSkill(vector, 1, string.Empty);
			}
			else
			{
				LootManager.DropItem(vector, 1, string.Empty);
			}
			break;
		}
		SoundManager.PlayAudioWithDistance("TreasureFare", vector);
		PoolManager.GetPoolItem<ConfettiEffect>().Emit(75, vector);
		Globals.ChaosInst<Explosion>(ChaosBundle.Get("Assets/Prefabs/Effects/Explosion.prefab"), transform.parent, vector).Explode();
		gameObject.SetActive(value: false);
	}
}

