			if (cardShuffleInitiated)
			{
				DialogManager.dialogDict[myDialogID].CurrentIndex = 4;
			}
			break;
		case 1:
		{
			for (int i = 0; i < 5; i++)
			{
				if (skillItems[i] == null)
				{
					DialogManager.dialogDict[myDialogID].CurrentIndex = 5;
					return false;
				}
			}
			playerHasToken = player.inventory.ContainsItem("TokenShuffler");
			if (!playerHasToken)
			{
				DialogManager.dialogDict[myDialogID].CurrentIndex = 2;
				return false;
			}
			break;
		}
		case 2:
			if (!cardShuffleInitiated && player != null)
			{
				InitCardShuffle();
				playerLeavingDialog = true;
				return true;
			}
			break;
		case 3:
			if (!cardShuffleInitiated && player != null && player.GetRandomStandardSkill() != null)
			{
				InitCardShuffle();
				playerLeavingDialog = true;
				return true;
			}
			break;
		case 4:
			if (!cardShuffleInitiated)
			{
				playerLeavingDialog = true;
				return true;
			}
			break;
		case 5:
			if (cardShuffleInitiated)
			{
				playerLeavingDialog = true;
				return true;
			}
			break;
		}
		return false;
	}

	private void InitCardShuffle()
	{
		cardShuffleInitiated = true;
		shuffledPlayer = player;
		RunData.miscSlotsRoomFound = true;
		SoundManager.PlayAudio("Shuffler0");
		StartCoroutine(ShuffleCards(playerHasToken));
	}

	private IEnumerator ShuffleCards(bool useToken)
	{
		shufflingInProgress = true;
		if (useToken)
		{
			shuffledPlayer.inventory.RemoveItem("TokenShuffler", forceOverride: false, showNotice: true);
		}
		else
		{
			shuffledPlayer.RemoveSkill(player.GetRandomStandardSkill(allowEmp: false) ?? player.GetRandomStandardSkill());
		}
		for (int i = 0; i < 5; i++)
		{
			currentSSItem = skillItems[i];
			if (!(currentSSItem == null))
			{
				currentSSItem.costStat.AddMod(costOverrideMod);
				currentSSItem.anim.Play("SpawnFlipped", -1, 0f);
				currentSSItem.SetAllowedPlayerID(shuffledPlayer.playerID);
			}
		}
		SoundManager.PlayAudioWithDistance("CardSpawn", transform.position);
		yield return waitForHideDelay;
		lerpStopwatch.IsRunning = true;
		isLerping = true;
		SoundManager.PlayAudio("CardShuffle");
		while (isLerping)
		{
			for (int j = 0; j < 5; j++)
			{
				skillItems[j].transform.position = Vector2.Lerp(shuffledVectors[j], centeredVectors[j], lerpStopwatch.TimePercentage);
			}
			isLerping = lerpStopwatch.IsRunning;
			yield return null;
		}
		yield return waitForGatherDelay;
		for (int k = 0; k < 4; k++)
		{
			StartCoroutine(SpinCard(skillItems[k].transform));
			yield return waitForSpinDelay;
		}
		yield return StartCoroutine(SpinCard(skillItems[4].transform));
		shuffledVectors.Shuffle();
		lerpStopwatch.IsRunning = true;
		isLerping = true;
		while (isLerping)
		{
			for (int l = 0; l < 5; l++)
			{
				skillItems[l].transform.position = Vector2.Lerp(centeredVectors[l], shuffledVectors[l], lerpStopwatch.TimePercentage);
			}
			isLerping = lerpStopwatch.IsRunning;
			yield return null;
		}
		for (int m = 0; m < 5; m++)
		{
			currentSSItem = skillItems[m];
			if (!(currentSSItem == null))
			{
				currentSSItem.overheadPromptHeight = 2.25f;
				currentSSItem.SetPromptTriggerStatus(status: true);
				currentSSItem.SetLightStatus(status: true);
				currentSSItem.anim.Play("Unflip", -1, UnityEngine.Random.Range(0f, 0.125f));
				SoundManager.PlayAudio("CardSelect");
			}
		}
		shufflingInProgress = false;
		pickingInProgress = true;
	}

	private IEnumerator SpinCard(Transform givenTrans)
	{
		Vector2 spinVector = Vector2.zero;
		int spinCount = 4;
		float minAngle = -(float)Math.PI / 2f;
		float maxAngle = (2f * (float)spinCount - 0.5f) * (float)Math.PI;
		float spinAngle = 0f;
		int spinStopwatchID = ChaosStopwatch.Begin(4f);
		bool isSpinning = true;
		float minRadius = 0f - givenTrans.localPosition.y;
		float maxRadius = 3f;
		float radiusValue = 0f;
		for (int i = 0; i < 5; i++)
		{
			skillItems[i].itemSpriteRenderer.sortingLayerName = "Overlay";
			skillItems[i].itemBGSpriteRenderer.sortingLayerName = "Overlay";
			skillItems[i].standardSR.sortingLayerName = "Overlay";
			skillItems[i].empoweredSR.sortingLayerName = "Overlay";
			skillItems[i].sigSR.sortingLayerName = "Overlay";
		}
		while (isSpinning)
		{
			float spinValue = Globals.GetSmoothLerpValue(ChaosStopwatch.GetTimePercentage(spinStopwatchID));
			spinAngle = Mathf.Lerp(minAngle, maxAngle, spinValue);
			spinVector.x = Mathf.Cos(spinAngle);
			spinVector.y = Mathf.Sin(spinAngle);
			radiusValue = Mathf.Lerp(minRadius, maxRadius, Mathf.PingPong(spinValue * 4f, 1f));
			if (spinValue > 0.25f && spinValue < 0.75f)
			{
				radiusValue = Mathf.Clamp(radiusValue, 0.25f, maxRadius);
			}
			if (!audioStopwatch.IsRunning)
			{
				audioStopwatch.SetDelay(Mathf.Lerp(0.2f, 0.0625f, Mathf.Pow(1f + Mathf.PingPong(spinValue * 2f, 1f), 2f) - 1f), stopCurrent: false, autoStart: true);
				SoundManager.PlayAudioWithDistance("CardSelect", transform.position);
			}
			givenTrans.position = currentPosition + spinVector * (radiusValue + 1f);
			isSpinning = !ChaosStopwatch.Check(spinStopwatchID);
			yield return null;
		}
		for (int j = 0; j < 5; j++)
		{
			skillItems[j].itemSpriteRenderer.sortingLayerName = "Actor";
			skillItems[j].itemBGSpriteRenderer.sortingLayerName = "Actor";
			skillItems[j].standardSR.sortingLayerName = "Actor";
			skillItems[j].empoweredSR.sortingLayerName = "Actor";
			skillItems[j].sigSR.sortingLayerName = "Actor";
		}
	}

	private void OnCardSelected(Player givenPlayer, StoreItem storeItem)
	{
		pickCounter++;
		SoundManager.PlayAudio("Powerup");
		if (pickCounter < allowedPickCount)
		{
			return;
		}
		pickingInProgress = false;
		for (int i = 0; i < 5; i++)
		{
			currentSSItem = skillItems[i];
			if (!(currentSSItem == null))
			{
				SkillStoreItem skillStoreItem = currentSSItem;
				skillStoreItem.buyEventHandlers = (StoreItem.BuyEventHandler)Delegate.Remove(skillStoreItem.buyEventHandlers, new StoreItem.BuyEventHandler(OnCardSelected));
				currentSSItem.SetPromptTriggerStatus(status: false);
				currentSSItem.anim.Play("Hide", -1, 0f);
			}
		}
	}
}
