public class CursedSeal : Item
{
	public static string staticID = "CursedSeal";

	private float dmgIncPerCurse = 0.05f;

	private float stunIncPerCurse = 0.25f;

	private float spdDecPerCurse = -0.05f;

	private NumVarStatMod damageMod;

	private NumVarStatMod hitStunMod;

	private NumVarStatMod speedMod;

	private Dictionary<string, NumVarStatMod> modDict;

	private int curseCount;

	private int calcCount;

	protected override string ExtraInfo => PercentToStr(damageMod, "+") + " | " + PercentToStr(speedMod, "-");

	public CursedSeal()
	{
		ID = staticID;
		category = Category.Offense;
		isCursed = true;
		damageMod = new NumVarStatMod(staticID, dmgIncPerCurse, 5, VarStatModType.Multiplicative);
		hitStunMod = new NumVarStatMod(staticID, stunIncPerCurse, 5);
		speedMod = new NumVarStatMod(staticID, spdDecPerCurse, 5, VarStatModType.Multiplicative);
		modDict = new Dictionary<string, NumVarStatMod>
		{
			{
				StatData.damageStr,
				damageMod
			},
			{
				StatData.stunDurStr,
				hitStunMod
			}
		};
	}

	public override void Activate()
	{
		SetEventHandlers(givenStatus: true);
	}

	public override void Deactivate()
	{
		SetEventHandlers(givenStatus: false);
	}

	private void SetEventHandlers(bool givenStatus)
	{
		if (!(parentEntity == null))
		{
			curseCount = 0;
			StatManager.ModifyAllStatData(modDict, parentSkillCategory, IgnoreStatusConditional, givenStatus);
			parentEntity.movement.moveSpeedStat.Modify(speedMod, givenStatus);
			Inventory inventory = parentEntity.inventory;
			inventory.inventoryChangeEventHandler = (Inventory.ItemEventHandler)Delegate.Remove(inventory.inventoryChangeEventHandler, new Inventory.ItemEventHandler(OnInventoryChange));
			if (givenStatus)
			{
				Inventory inventory2 = parentEntity.inventory;
				inventory2.inventoryChangeEventHandler = (Inventory.ItemEventHandler)Delegate.Combine(inventory2.inventoryChangeEventHandler, new Inventory.ItemEventHandler(OnInventoryChange));
				OnInventoryChange(null, givenStatus: false);
			}
		}
	}

	private void OnInventoryChange(Item givenItem, bool givenStatus)
	{
		calcCount = parentEntity.inventory.CursedCount;
		if (calcCount != curseCount)
		{
			curseCount = calcCount;
			damageMod.modValue = dmgIncPerCurse * (float)curseCount;
			hitStunMod.modValue = stunIncPerCurse * (float)curseCount;
			speedMod.modValue = spdDecPerCurse * (float)curseCount;
			parentEntity.movement.moveSpeedStat.Modify(speedMod, addMod: true);
		}
	}
}
