public class CursedAura : MonoBehaviour
{
	public FollowTransform followComp;

	public ParticleSystem fgEmitter;

	public ParticleSystem bgEmitter;

	private ParticleSystem.EmissionModule fgEmitterMod;

	private ParticleSystem.EmissionModule bgEmitterMod;

	private GameObject parentGameObj;

	public void Start()
	{
		fgEmitterMod = fgEmitter.emission;
		bgEmitterMod = bgEmitter.emission;
		gameObject.SetActive(value: false);
	}

	public void Play(GameObject givenObj, Vector3 givenOffset)
	{
		if (!(givenObj == null))
		{
			gameObject.SetActive(value: true);
			parentGameObj = givenObj;
			transform.position = givenObj.transform.position;
			followComp.followTransform = givenObj.transform;
			followComp.followOffset = givenOffset;
			fgEmitter.time = Random.Range(0f, 1f);
			bgEmitter.time = Random.Range(0f, 1f);
			fgEmitter.Play();
			bgEmitter.Play();
		}
	}

	public void Update()
	{
		if (parentGameObj == null || !parentGameObj.activeSelf)
		{
			Reset();
		}
	}

	public void Reset()
	{
		followComp.followTransform = null;
		followComp.followOffset = Vector3.zero;
		fgEmitter.Stop();
		bgEmitter.Stop();
		gameObject.SetActive(value: false);
	}
