using Chaos.AnimatorExtensions;
using UnityEngine;

public class MimicNpc : Npc
{
	private static GameObject prefab;

	private WeightedRandomizer openAnimRandomizer;

	private WeightedRandomizer closeAnimRandomizer;

	private ChaosQuickStopwatch animStopwatch;

	private bool closed = true;

	private string nextAnim = "Closed";

	private string lastAnim = "Closed";

	private bool dialogCompleted;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Allies/Mimic.prefab"));

	public override void Awake()
	{
		base.Awake();
		openAnimRandomizer = new WeightedRandomizer();
		openAnimRandomizer.Add(new WeightedItem("LookLeft", 5));
		openAnimRandomizer.Add(new WeightedItem("LookRight", 5));
		openAnimRandomizer.Add(new WeightedItem("Opened", 20));
		openAnimRandomizer.Add(new WeightedItem("Blink", 30));
		openAnimRandomizer.Add(new WeightedItem("Close", 10));
		closeAnimRandomizer = new WeightedRandomizer();
		closeAnimRandomizer.Add(new WeightedItem("Peek", 10));
		closeAnimRandomizer.Add(new WeightedItem("Open", 10));
	}

	public override void Start()
	{
		base.Start();
		animStopwatch = new ChaosQuickStopwatch(Random.Range(4f, 7f));
		animStopwatch.IsRunning = true;
	}

	public override void Update()
	{
		if (!animStopwatch.IsRunning && anim.AnimPlayed())
		{
			nextAnim = "Closed";
			if (closed)
			{
				for (int i = 0; i < 5; i++)
				{
					nextAnim = closeAnimRandomizer.GetRandomItem().name;
					if (nextAnim != lastAnim)
					{
						break;
					}
				}
			}
			else
			{
				for (int j = 0; j < 5; j++)
				{
					nextAnim = openAnimRandomizer.GetRandomItem().name;
					if ((!isSpeaking || !(nextAnim == "Close")) && nextAnim != lastAnim)
					{
						break;
					}
				}
			}
			anim.Play(nextAnim, -1, 0f);
			lastAnim = nextAnim;
			if (nextAnim == "Close")
			{
				closed = true;
			}
			else if (nextAnim == "Open")
			{
				closed = false;
			}
			animStopwatch.SetDelay(Random.Range(4f, 7f), stopCurrent: false, autoStart: true);
		}
		if (!(player != null) || !PlayerRoomUI.CurrentUI.IsUsingSpellBook(player))
		{
			base.Update();
		}
	}

	public override void Interacted()
	{
		if (!(player != null) || !PlayerUIBase.GetLock("RelicChestUI" + player.playerID))
		{
			if (dialogCompleted || PlayerRoomUI.CurrentUI.AnyUIOpen)
			{
				CurrentOverheadPrompt = null;
				Exiting();
			}
			else
			{
				base.Interacted();
			}
		}
	}

	public override void InteractEvent()
	{
		if (!isSpeaking)
		{
			if (closed)
			{
				anim.Play("Open");
				closed = false;
			}
			else if (anim.AnimPlayed())
			{
				anim.Play("Jump", -1, 0f);
			}
			animStopwatch.SetDelay(Random.Range(4f, 7f), stopCurrent: false, autoStart: true);
		}
	}

	public override void Exiting()
	{
		Player player = base.player;
		base.Exiting();
		if (!myDialogID.EndsWith("Ending"))
		{
			if (!PlayerRoomUI.CurrentUI.IsUsingRelicChest(player))
			{
				PlayerRoomUI.CurrentUI.OpenRelicChest(player, transform.position);
			}
			dialogCompleted = true;
		}
	}

	public override void OnTriggerStay2D(Collider2D col)
	{
		if (col.gameObject.name == "AllyFloorContact")
		{
			Player component = col.transform.parent.gameObject.GetComponent<Player>();
			if (player == null && component != null && !PlayerRoomUI.CurrentUI.IsUsingRelicChest(component))
			{
				player = component;
				CurrentOverheadPrompt.Initialize(transform, player.inputDevice.inputScheme, overheadPromptHeight);
				CurrentOverheadPrompt.DisplayPrompt("Interact");
			}
		}
	}
}

