	private int GetEnemyCount()
	{
		int num = 0;
		SurvivalRoom[] array = survivalRooms;
		foreach (SurvivalRoom survivalRoom in array)
		{
			EnemyFactory[] enemyFactories = survivalRoom.enemyFactories;
			foreach (EnemyFactory enemyFactory in enemyFactories)
			{
				num += (enemyFactory.maxSpawnCycles - enemyFactory.currentSpawnCycle) * enemyFactory.enemiesPerCycle;
			}
			Enemy[] componentsInChildren = survivalRoom.transform.parent.Find("EnemyLocations").GetComponentsInChildren<Enemy>();
			foreach (Enemy enemy in componentsInChildren)
			{
				if (!enemy.fsm.currentStateName.Contains("Dead"))
				{
					num++;
				}
			}
		}
		return num;
	}

	private void EditPlayerSkills(bool remove = true)
	{
		if (remove)
		{
			Player[] activePlayers = GameController.activePlayers;
			foreach (Player player in activePlayers)
			{
				if (player.fsm.currentStateName.Contains("Dead"))
				{
					continue;
				}
				for (int j = 0; j < 6; j++)
				{
					int key = j + player.playerID * 6;
					if (player.assignedSkills[j] != null && player.assignedSkills[j].name != "Slash" && player.assignedSkills[j].name != "Dash")
					{
						removedSkills.Add(key, player.assignedSkills[j]);
						player.AssignSkillSlot(j + 1, string.Empty);
					}
				}
				player.lowerHUD.cooldownUI.RefreshEntries();
			}
			return;
		}
		Player[] activePlayers2 = GameController.activePlayers;
		foreach (Player player2 in activePlayers2)
		{
			for (int l = 0; l < 6; l++)
			{
				int key = l + player2.playerID * 6;
				if (removedSkills.ContainsKey(key))
				{
					player2.AssignSkillSlot(l + 1, removedSkills[key].skillID);
				}
			}
			player2.lowerHUD.cooldownUI.RefreshEntries();
		}
	}

	private void HandleChallengeComplete()
	{
		if (challengeType == ChallengeType.SkillRemoval)
		{
			EditPlayerSkills(remove: false);
		}
		ToggleNPC(on: true, includeOverheadImage: false);
		TreasureChest component = Object.Instantiate(ChaosBundle.Get("Assets/Prefabs/Environment/Destructibles/TreasureChest.prefab"), transform.position + Vector3.down * 2f, Quaternion.identity).GetComponent<TreasureChest>();
		if (rewardLootTableName != string.Empty)
		{
			component.lootTableName = rewardLootTableName;
		}
		enabled = false;
	}

	private void ToggleNPC(bool on, bool includeOverheadImage = true)
	{
		spriteObject.SetActive(on);
		CircleCollider2D[] array = circColliders;
		foreach (CircleCollider2D circleCollider2D in array)
		{
			circleCollider2D.enabled = on;
		}
		if (includeOverheadImage)
		{
			playerScript.overheadPrompt.DisplayPrompt("Interact");
		}
		if (!on)
		{
			playerScript.overheadPrompt.HidePrompt(string.Empty);
		}
	}

	private ChallengeStatus CheckChallengeStatus()
	{
		bool flag = false;
		SurvivalRoom[] array = survivalRooms;
		foreach (SurvivalRoom survivalRoom in array)
		{
			if (!survivalRoom.triggered)
			{
				continue;
			}
			flag = true;
			if (challengeType == ChallengeType.NoDamage)
			{
				for (int j = 0; j < GameController.activePlayers.Length; j++)
				{
					Player player = GameController.activePlayers[j];
					if (player != null && (player.fsm.currentStateName.Contains("Hurt") || (player.fsm.currentStateName.Contains("Dead") && !playerDead[j])))
					{
						return ChallengeStatus.Failed;
					}
				}
			}
			if (!survivalRoom.CheckPlayers())
			{
				return ChallengeStatus.Failed;
			}
			if (!survivalRoom.roomCleared)
			{
				return ChallengeStatus.InProgress;
			}
		}
		if (!flag)
		{
			return ChallengeStatus.NotStarted;
		}
		return ChallengeStatus.Completed;
	}

	private void OnTriggerStay2D(Collider2D col)
	{
		if (Entity.GetAllTargetsInRange(GameController.enemies, transform.position, 8f).Count > 0)
		{
			if (playerScript != null)
			{
				playerScript.fsm.ChangeState(playerScript.fsm.defaultStateName);
			}
			questionBox.SetActive(value: false);
			OnTriggerExit2D(col);
		}
		else if (col.gameObject.name == "AllyHurtBox" && enabled && col.transform.parent.gameObject.GetComponent<Player>() != null && currentInput == null)
		{
			playerScript = GameController.playerScripts[col.transform.parent.gameObject.GetComponent<Player>().playerID];
			currentInput = playerScript.inputDevice;
			playerScript.overheadPrompt.DisplayPrompt("Interact");
		}
	}

	private void OnTriggerExit2D(Collider2D col)
	{
		if (col.gameObject.name == "AllyHurtBox" && col.transform.parent.gameObject.GetComponent<Player>() != null && playerScript == GameController.playerScripts[col.transform.parent.gameObject.GetComponent<Player>().playerID])
		{
			playerScript.overheadPrompt.HidePrompt(string.Empty);
			playerScript = null;
			currentInput = null;
		}
	}

