public class HealStoreItem : StoreItem
{
	public delegate void SpawnEventHandler(HealStoreItem item);

	public new delegate void BuyEventHandler(HealStoreItem item);

	private const int healCostIncrease = 0;

	public float healPercentage;

	public static int healBuyCount = 0;

	private static float healDecrease = 0.05f;

	public static SyncedNumVarStat healDecreaseStat = new SyncedNumVarStat(healDecrease);

	public static SpawnEventHandler spawnEventHandlers;

	public new static BuyEventHandler buyEventHandlers;

	public static List<HealStoreItem> healItemList = new List<HealStoreItem>();

	public bool disableMarkerOffset;

	private GameObject ghostObj;

	public bool allowRestock = true;

	public override void Awake()
	{
		TextManager.SetUITextByScale(itemText = transform.Find("Canvas/ItemName").GetComponent<Text>());
		base.Awake();
	}

	public override void Start()
	{
		overheadPromptHeight = 2.875f;
		costStat.AddMod(new NumVarStatMod("HealCostIncrease", 0 * healBuyCount));
		base.Start();
		itemText.text = TextManager.GetItemName("HealingPotion");
		healItemList.RemoveNullValues();
		healItemList.Add(this);
		if (spawnEventHandlers != null)
		{
			spawnEventHandlers(this);
		}
		if (!disableMarkerOffset)
		{
			priceMarker.OffsetSortValue(priceMarkerYOffset);
		}
	}

	public override bool Buy(Player player)
	{
		if (!base.Buy(player))
		{
			return false;
		}
		Player[] activePlayers = GameController.activePlayers;
		foreach (Player player2 in activePlayers)
		{
			if (!(player2 == null))
			{
				if (player2.fsm.currentStateName.Contains("Dead"))
				{
					player2.ResetPlayer(originPosition: false, fullyRestoreHealth: false, resetState: true, resetOverdrive: true, 0.25f);
					player2.TeleportToPartner();
				}
				else if (player2.health.CurrentHealthValue > 0)
				{
					player2.health.RestoreHealth(GetHealValue(player2));
					Object.Instantiate(HealthPowerup.EffectPrefab, player2.transform.position, Quaternion.identity);
				}
			}
		}
		for (int num = GameController.ghosts.Count - 1; num >= 0; num--)
		{
			ghostObj = GameController.ghosts[num];
			if (ghostObj != null && ghostObj.GetComponent<Ghost>() != null)
			{
				ghostObj.GetComponent<Ghost>().DestroyGhost();
			}
		}
		RunData.reqItemStoreFound = true;
		healBuyCount++;
		if (buyEventHandlers != null)
		{
			buyEventHandlers(this);
		}
		Object.Destroy(gameObject);
		return true;
	}

	public override void HandleGoldEndStat(Player givenPlayer = null)
	{
		int num = GameController.activePlayers.Length;
		int value = Mathf.FloorToInt((float)Cost / (float)num);
		Player[] activePlayers = GameController.activePlayers;
		foreach (Player player in activePlayers)
		{
			if (player != null)
			{
				player.stats.ModifyValue(PlayerEndStats.Stat.Spent, value);
			}
		}
	}

	private int GetHealValue(Player givenPlayer)
	{
		return Mathf.Max(50, Mathf.CeilToInt(givenPlayer.health.healthStat.ModifiedValue * (healPercentage - (float)healBuyCount * healDecreaseStat.CurrentValue)));
	}
}

