public class JewelerNpc : Npc
{
	private int cost = 20;

	private int goldReturn = 200;

	public static bool goldTraded;

	private int endDialogIndex = 3;

	public override void Start()
	{
		base.Start();
		if (GameController.resetHubVars)
		{
			goldTraded = false;
		}
