	public override bool HandleConditionalInteraction()
	{
		if (goldTraded && CurrentDialogIndex < endDialogIndex)
		{
			CurrentDialogIndex = endDialogIndex;
			return false;
		}
		switch (CurrentDialogIndex)
		{
		case 1:
			if (Player.platWallet.balance >= cost)
			{
				CurrentDialogIndex = 2;
			}
			break;
		case 2:
			playerLeavingDialog = true;
			return true;
		case 3:
			goldTraded = true;
			Player.goldWallet.Deposit(goldReturn);
			Player.platWallet.Withdraw(cost);
			SoundManager.PlayAudio("MenuBuy");
			SoundManager.PlayAudio("Jeweler0");
			PoolManager.GetPoolItem<EmoteEmitter>().Emit(EmoteType.AwwYis, 1, transform.position + Vector3.up * 2.75f);
			break;
		}
		return false;
	}
}
