using System.Collections;
using UnityEngine;
public class JukeboxNpc : Npc
{
	private static GameObject prefab;
	public SpriteRenderer albumIndicatorSprite;
	public Sprite[] albumIndicatorSprites;
	private const int EndDialogIndex = 4;
	private int albumDialog = 1;
	private bool trackChanged;
	private Vector2 fxPosition;
	private ParticleEffect noteEmitter;
	private static WaitForSeconds waitForNote = new WaitForSeconds(0.35f);
	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Allies/JukeboxNpc.prefab"));
	public override void Start()
	{
		base.Start();
		SetAlbumIndicator(SoundManager.bgmTrack);
		albumDialog = (int)(SoundManager.bgmTrack + 1);
	}
	public override void Interacted()
	{
		if (!isSpeaking)
		{
			anim.Play("Interact", -1, 0f);
		}
		base.Interacted();
	}
	public override bool HandleConditionalInteraction()
	{
		switch (CurrentDialogIndex)
		{
		case 1:
			CurrentDialogIndex = albumDialog;
			break;
		case 2:
			SelectAlbum(BGMTrackType.Jazz);
			break;
		case 3:
			SelectAlbum(BGMTrackType.Piano);
			break;
		case 4:
			SelectAlbum(BGMTrackType.Original);
			break;
		}
		return false;
	}
	private void SelectAlbum(BGMTrackType givenType)
	{
		StartCoroutine(HandleTransition(givenType));
		albumDialog++;
		if (albumDialog > 3)
		{
			albumDialog = 1;
		}
		PlayDefaultEmote();
		anim.Play("Dance", -1, 0f);
		SetAlbumIndicator(givenType);
		SoundManager.PlayAudio("StandardChestSpawn");
		CurrentDialogIndex = 4;
		trackChanged = true;
	}
	private void SetAlbumIndicator(BGMTrackType givenType)
	{
		switch (givenType)
		{
		case BGMTrackType.Original:
			albumIndicatorSprite.enabled = false;
			break;
		case BGMTrackType.Jazz:
			albumIndicatorSprite.sprite = albumIndicatorSprites[0];
			albumIndicatorSprite.enabled = true;
			break;
		case BGMTrackType.Piano:
			albumIndicatorSprite.sprite = albumIndicatorSprites[1];
			albumIndicatorSprite.enabled = true;
			break;
		}
	}
	public override void OnTriggerEnter2D(Collider2D col)
	{
		if (!trackChanged)
		{
			base.OnTriggerEnter2D(col);
		}
	}
	public override void OnTriggerStay2D(Collider2D col)
	{
		if (!trackChanged)
		{
			base.OnTriggerStay2D(col);
		}
	}
	public override void OnTriggerExit2D(Collider2D col)
	{
		base.OnTriggerExit2D(col);
		trackChanged = false;
	}
	private IEnumerator HandleTransition(BGMTrackType givenType)
	{
		GameDataManager.gameVars.SetValue(GameVarsKey.BgmTrack, (int)givenType);
		GameDataManager.SaveGameVars();
		yield return null;
		SoundManager.bgmTrack = givenType;
		SoundManager.PlayBGM("PlayerRoom");
		yield return null;
		fxPosition = transform.position + Vector3.up;
		for (int i = 0; i < 5; i++)
		{
			PoolManager.GetPoolItem<ParticleEffect>("SparkleAura").Emit(3, fxPosition + new Vector2(Random.Range(-0.75f, 0.75f), 0.25f), ParticleEffectOverrides.LayerOverlayDoodad);
			EmitNote();
			yield return null;
		}
		yield return waitForNote;
		while (trackChanged || SoundManager.BGMTransitionInProgress)
		{
			EmitNote();
			yield return waitForNote;
		}
		anim.Play("Idle");
	}
	private void EmitNote()
	{
		if (noteEmitter == null)
		{
			noteEmitter = PoolManager.GetPoolItem<ParticleEffect>("MusicNoteEmitter");
		}
		noteEmitter.Emit(1, fxPosition + new Vector2(Random.Range(-1.125f, 1f), Random.Range(1f, 1.5f)), ParticleEffectOverrides.LayerOverlayDoodad);
	}
}
using UnityEngine;
public class MuseumNpc : Npc
{
	private bool skillAssigned;
	private MuseumTutorial museumTutorial;
	public override void Start()
	{
		base.Start();
		headLeftOffset = new Vector3(-0.0625f, 0f, 0f);
		if (myDialogID == "MuseumFinalEventNpc")
		{
			museumTutorial = GameObject.Find("Museum").GetComponent<MuseumTutorial>();
			autoDisableNpc = true;
		}
		if (defaultXScale == -1f)
		{
			FacePlayer(transform.position.x - 10f);
		}
	}
	public override bool HandleConditionalInteraction()
	{
		switch (myDialogID)
		{
		case "MuseumWorker-Lobby":
			if (CurrentDialogIndex == 1 && player.HasSkill(Player.DashState.staticID))
			{
				playerLeavingDialog = true;
				return true;
			}
			break;
		case "MuseumWorker-Arcana":
			if (CurrentDialogIndex == 0 && player.HasSkill(Player.WindSlashBasic.staticID))
			{
				CurrentDialogIndex = 2;
			}
			break;
		case "MuseumWorker-Signature":
			if (CurrentDialogIndex == 0 && player.HasSkill(Player.ShootFireball.staticID))
			{
				CurrentDialogIndex = 1;
			}
			break;
		}
		return false;
	}
	public override void Exiting()
	{
		switch (myDialogID)
		{
		case "MuseumWorker-Lobby":
			if (!player.HasSkill(Player.DashState.staticID))
			{
				AssignSkillToPlayers(Player.DashState.staticID, 1);
			}
			break;
		case "MuseumWorker-Arcana":
			if (!player.HasSkill(Player.WindSlashBasic.staticID))
			{
				AssignSkillToPlayers(Player.WindSlashBasic.staticID, 0);
				AssignSkillToPlayers(Player.DashState.staticID, 1);
				AssignSkillToPlayers(Player.ShootFireArc.staticID, 2);
			}
			break;
		case "MuseumWorker-Signature":
			if (!player.HasSkill(Player.ShootFireball.staticID))
			{
				AssignSkillToPlayers(Player.WindSlashBasic.staticID, 0);
				AssignSkillToPlayers(Player.DashState.staticID, 1);
				AssignSkillToPlayers(Player.ShootFireArc.staticID, 2);
				AssignSkillToPlayers(Player.ShootFireball.staticID, 3, setSig: true);
			}
			break;
		case "MuseumWorker-Course":
			autoTriggerDialog = false;
			if (!player.HasSkill(Player.ShootFireball.staticID))
			{
				AssignSkillToPlayers(Player.WindSlashBasic.staticID, 0);
				AssignSkillToPlayers(Player.DashState.staticID, 1);
				AssignSkillToPlayers(Player.ShootFireArc.staticID, 2);
				AssignSkillToPlayers(Player.ShootFireball.staticID, 3, setSig: true);
			}
			break;
		case "MuseumFinalEventNpc":
			museumTutorial.StartCoroutine(museumTutorial.StartAdventure());
			break;
		}
		base.Exiting();
	}
	public void AssignSkillToPlayers(string givenSkillID, int givenSlot = -1, bool setSig = false)
	{
		Player[] activePlayers = GameController.activePlayers;
		foreach (Player player in activePlayers)
		{
			if (player == null || player.HasSkill(givenSkillID))
			{
				continue;
			}
			if (givenSlot == -1 || player.assignedSkills[givenSlot] != null)
			{
				givenSlot = player.GetEmptySkillSlot();
				if (givenSlot == -1)
				{
					continue;
				}
			}
			player.AssignSkillSlot(givenSlot, givenSkillID, setSig, setSig);
			player.lowerHUD.cooldownUI.RefreshEntries();
			player.newItemNoticeUI.Display(TextManager.GetSkillName(givenSkillID), IconManager.GetSkillIcon(givenSkillID), CooldownUI.GetKeySpriteFromSkillSlot(givenSlot, player.inputDevice), isSkill: true);
			SoundManager.PlayAudio("Powerup");
		}
	}
}
