using System;
public class DoctorDiscount : Item
{
	public static string staticID = "DoctorDiscount";
	private NumVarStatMod costMod;
	public DoctorDiscount()
	{
		ID = staticID;
		category = Category.Misc;
		combineOnly = true;
		parentGroupID = DiscountGroupItem.staticID;
		costMod = new NumVarStatMod(ID, 25f, 10, VarStatModType.Override);
	}
	public override void Activate()
	{
		SetEventHandlers(givenStatus: true);
	}
	public override void Deactivate()
	{
		SetEventHandlers(givenStatus: false);
	}
	private void SetEventHandlers(bool givenStatus)
	{
		if (givenStatus && GroupItemCreated(parentGroupID))
		{
			return;
		}
		foreach (HealStoreItem healItem in HealStoreItem.healItemList)
		{
			ApplyCostMod(healItem, givenStatus);
		}
		HealStoreItem.spawnEventHandlers = (HealStoreItem.SpawnEventHandler)Delegate.Remove(HealStoreItem.spawnEventHandlers, new HealStoreItem.SpawnEventHandler(OnHealSpawn));
		if (givenStatus)
		{
			HealStoreItem.spawnEventHandlers = (HealStoreItem.SpawnEventHandler)Delegate.Combine(HealStoreItem.spawnEventHandlers, new HealStoreItem.SpawnEventHandler(OnHealSpawn));
		}
	}
	private void OnHealSpawn(HealStoreItem givenItem)
	{
		ApplyCostMod(givenItem, givenStatus: true);
	}
	private void ApplyCostMod(HealStoreItem givenItem, bool givenStatus)
	{
		if (!(givenItem == null))
		{
			givenItem.costStat.Modify(costMod, givenStatus);
			givenItem.UpdatePrice();
		}
	}
}
